def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    obj_winner = objective[b_idx, winner_idx]
    obj_loser = objective[b_idx, loser_idx]
    weight = (obj_loser - obj_winner).to(dtype=obj_loser.dtype)
    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx.long(), winner_idx.long(), loser_idx.long()),
        weight=weight,
        meta={'builder': 'all_pairs_obj_gap_linear'}
